import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"The recovery workflow (WinRE-style)","description":"","frontmatter":{},"headers":[],"relativePath":"manual/recovery.md","filePath":"manual/recovery.md"}'),r={name:"manual/recovery.md"};function n(i,e,l,c,h,d){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-recovery-workflow-winre-style" tabindex="-1">The recovery workflow (WinRE-style) <a class="header-anchor" href="#the-recovery-workflow-winre-style" aria-label="Permalink to &quot;The recovery workflow (WinRE-style)&quot;">​</a></h1><p>Open Cube OS <em>is</em> the recovery environment. Where Windows hides WinRE behind a boot failure, here the <code>oc&gt;</code> shell is the primary interface - and it doubles as the rescue kit for the machine it runs on.</p><h2 id="posture" tabindex="-1">Posture <a class="header-anchor" href="#posture" aria-label="Permalink to &quot;Posture&quot;">​</a></h2><ul><li>The system boots to a shell even with <strong>no disk at all</strong> (the ISO is self-contained).</li><li>Every diagnostic is a shell command away - no separate rescue medium to build, no special mode to enter.</li><li>Crash artifacts persist to the /etc volume, so a machine that reboots after a panic still carries its own evidence.</li></ul><h2 id="crash-artifacts" tabindex="-1">Crash artifacts <a class="header-anchor" href="#crash-artifacts" aria-label="Permalink to &quot;Crash artifacts&quot;">​</a></h2><p>When the kernel panics (unhandled exception outside the guarded self-test):</p><ol><li>The exception frame (registers, fault address) dumps to serial - you see it with <code>-serial file:log.txt</code>.</li><li>A crashlog entry is written to the /etc volume.</li><li>The machine halts (or reboots, per the watchdog policy).</li></ol><p>After rebooting:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dumpinfo            (inspect the saved crash dump)</span></span>
<span class="line"><span>oc&gt; dmesg               (kernel ring buffer from the current boot)</span></span>
<span class="line"><span>oc&gt; logcat              (follow the persistent kernel log live)</span></span>
<span class="line"><span>oc&gt; ls /etc             (crashlog files live here)</span></span></code></pre></div><h2 id="forcing-a-crash-to-test-the-path" tabindex="-1">Forcing a crash (to test the path) <a class="header-anchor" href="#forcing-a-crash-to-test-the-path" aria-label="Permalink to &quot;Forcing a crash (to test the path)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; crashtest           (deliberate kernel panic - safe on a scratch</span></span>
<span class="line"><span>                          system, everything not on /etc is lost)</span></span></code></pre></div><p><code>crashtest</code> proves the dump path end-to-end: panic -&gt; serial dump -&gt; / etc crashlog -&gt; <code>dumpinfo</code> reads it back.</p><h2 id="the-rescue-kit" tabindex="-1">The rescue kit <a class="header-anchor" href="#the-rescue-kit" aria-label="Permalink to &quot;The rescue kit&quot;">​</a></h2><p>Typical rescue scenarios and their commands:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Do this</th></tr></thead><tbody><tr><td>System boots, then misbehaves</td><td><code>dmesg</code>, <code>logcat</code>, <code>health</code>, <code>health export</code> for a JSON snapshot</td></tr><tr><td>A user program hangs</td><td>task list + kill through the process commands; <code>watchdog</code> policy kills starvers</td></tr><tr><td>Suspicious disk</td><td><code>dskstat</code>, <code>fsck &lt;dev&gt;</code>, mount read-only to inspect</td></tr><tr><td>Boot flag points at a bad slot</td><td>GRUB menu -&gt; force the other slot; then <code>update rollback</code></td></tr><tr><td>Lost network config</td><td><code>config restore</code> (defaults) then re-run <code>dhcp</code></td></tr><tr><td>Log overflow</td><td><code>logctl</code> (level + filters), rotation is automatic (<code>kernel.log</code> -&gt; <code>kernel.log.1</code>)</td></tr></tbody></table><h2 id="watchdogs-the-hardware-side" tabindex="-1">Watchdogs (the hardware side) <a class="header-anchor" href="#watchdogs-the-hardware-side" aria-label="Permalink to &quot;Watchdogs (the hardware side)&quot;">​</a></h2><p><code>kernel/core/core_watchdog.c</code> arms real hardware watchdogs where the platform has them:</p><ul><li><strong>Intel TCO</strong> (LPC bus): discovered live on QEMU q35 - the E2E suite shows <code>Intel TCO found: PMBASE=0x600 TCOBASE=0x660</code>, arms it, starves it, and the machine genuinely hard-resets and boots again.</li><li><strong>ACPI WDAT</strong>: the table&#39;s entries are programmed; arming and the reset are verified the same way.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; watchdog            (status: hardware support + monitored slots)</span></span>
<span class="line"><span>oc&gt; watchdog feed       (feed the active watchdog)</span></span>
<span class="line"><span>oc&gt; watchdog start/stop/timeout ...   (see the command page)</span></span></code></pre></div><p>Monitored slots additionally implement a <em>policy</em> watchdog: tasks that must periodically feed their slot get killed (with the reason in the log) without taking the kernel down - the kernel survives, the offender does not.</p><h2 id="health-monitoring" tabindex="-1">Health monitoring <a class="header-anchor" href="#health-monitoring" aria-label="Permalink to &quot;Health monitoring&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; health              (CPU / memory / tasks / IO at a glance)</span></span>
<span class="line"><span>oc&gt; health watch        (live monitor, 1 s refresh)</span></span>
<span class="line"><span>oc&gt; health export       (JSON snapshot to /var/log/health.json)</span></span></code></pre></div><p>Thresholds raise alarms into the kernel log (<code>CPU-LOCKED</code> when a spinner pins a core, memory pressure, IO stall) - the alarm lines are what the E2E suite asserts on.</p>`,23)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
